// Cleanup all demo data generated by demo-api.mjs
// Run BEFORE demo-api.mjs to ensure a clean slate

const BASE = process.env.APP_URL || "http://localhost:3000";
const EMAIL = process.env.EMAIL || "admin@sifex.com";
const PASSWORD = process.env.PASSWORD || "Sifex@Admin2025!";

const csrfResp = await fetch(`${BASE}/api/auth/csrf`, { method: "GET" });
const csrfCookie = csrfResp.headers.get("set-cookie") || "";
const csrfBody = await csrfResp.json();
const csrfToken = csrfBody.csrfToken || "";

const loginResp = await fetch(`${BASE}/api/auth/callback/credentials`, {
  method: "POST",
  headers: {
    "Content-Type": "application/x-www-form-urlencoded",
    Cookie: csrfCookie.split(";")[0],
  },
  body: `csrfToken=${encodeURIComponent(csrfToken)}&email=${encodeURIComponent(EMAIL)}&password=${encodeURIComponent(PASSWORD)}`,
  redirect: "manual",
});
const cookies = loginResp.headers.get("set-cookie") || "";
if (!cookies.includes("authjs.session-token") && !cookies.includes("__Secure-authjs.session-token")) {
  // try following redirect
  const loginResp2 = await fetch(`${BASE}/api/auth/callback/credentials`, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      Cookie: csrfCookie.split(";")[0],
    },
    body: `csrfToken=${encodeURIComponent(csrfToken)}&email=${encodeURIComponent(EMAIL)}&password=${encodeURIComponent(PASSWORD)}`,
  });
  const c2 = loginResp2.headers.get("set-cookie") || "";
  if (c2) cookies = c2;
}

async function cleanEndpoint(path, param, count) {
  let deleted = 0;
  for (let page = 1; page <= 20; page++) {
    const resp = await fetch(`${BASE}/api/${path}?limit=50&page=${page}`, { headers: { Cookie: cookies } });
    const data = await resp.json();
    const items = data.data || data.records || [];
    for (const item of items) {
      if (param && !item[param]?.startsWith("071-")) continue;
      const delResp = await fetch(`${BASE}/api/${path}/${item.id}`, {
        method: "DELETE",
        headers: { Cookie: cookies },
      }).catch(() => null);
      if (delResp && delResp.ok) deleted++;
    }
    if (items.length < 50) break;
  }
  return deleted;
}

let total = 0;

// Clean billing records first (no DELETE endpoint, so mark void)
const billResp = await fetch(`${BASE}/api/billing?limit=500`, { headers: { Cookie: cookies } });
const billData = await billResp.json();
const bills = billData.data || [];
for (const b of bills) {
  if (b.totalAmount === 0 || b.invoiceNumber?.startsWith("INV-")) {
    await fetch(`${BASE}/api/billing/${b.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json", Cookie: cookies },
      body: JSON.stringify({ status: "VOID" }),
    }).catch(() => {});
    total++;
  }
}

// Clean delivery tasks
const delResp = await fetch(`${BASE}/api/delivery?limit=500`, { headers: { Cookie: cookies } });
const delData = await delResp.json();
const deliveries = delData.data || [];
for (const d of deliveries) {
  if (!d.trackingNumber?.startsWith("SIF-")) continue;
  await fetch(`${BASE}/api/delivery/${d.id}`, {
    method: "DELETE",
    headers: { Cookie: cookies },
  }).catch(() => {});
  total++;
}

// Clean MAWBs (HAWBs cascade? no, but we delete MAWB which will orphan HAWBs — OK since billing is already cleaned)
// Actually HAWBs aren't deleted by cascade. Let's find HAWBs for demo MAWBs and delete them.
const hawbResp = await fetch(`${BASE}/api/house-awbs?limit=500`, { headers: { Cookie: cookies } });
const hawbData = await hawbResp.json();
const hawbs = hawbData.data || [];
for (const h of hawbs) {
  if (!h.houseAWBNumber?.startsWith("HKG-")) continue;
  await fetch(`${BASE}/api/house-awbs/${h.id}`, {
    method: "DELETE",
    headers: { Cookie: cookies },
  }).catch(() => {});
  total++;
}

// Finally clean MAWBs
const mawbResp = await fetch(`${BASE}/api/master-awbs?limit=500`, { headers: { Cookie: cookies } });
const mawbData = await mawbResp.json();
const mawbs = mawbData.data || [];
for (const m of mawbs) {
  if (!m.awbNumber?.startsWith("071-")) continue;
  await fetch(`${BASE}/api/master-awbs/${m.id}`, {
    method: "DELETE",
    headers: { Cookie: cookies },
  }).catch(() => {});
  total++;
}

console.log(`Cleaned ${total} records`);
